import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Send, FileText, Video, X, Clock, User, Check, 
  Download, Calendar, Mail, ChevronDown, ChevronUp, Bot 
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { useToast } from "@/hooks/use-toast";
import { getUser, type User as AppUser } from "@/lib/auth";

interface Message {
  id: string;
  sender: "user" | "consultant" | "system" | "ai";
  text: string;
  timestamp: Date;
  attachments?: { name: string; type: string; url?: string }[];
  suggestions?: string[];
}

interface ConsultantChatProps {
  userName: string;
  userType: "school" | "graduate" | "student";
  dream?: string;
  recommendations?: string[];
  universities?: string[];
  meetingTime: string | null;
  onClose?: () => void;
  onOpenCalendar?: () => void;
}

const ConsultantChat = ({ 
  userName, 
  userType, 
  dream, 
  recommendations = [], 
  universities = [],
  meetingTime,
  onClose,
  onOpenCalendar,
}: ConsultantChatProps) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [showProfile, setShowProfile] = useState(true);
  const [videoCallActive, setVideoCallActive] = useState(false);
  const [callMissed, setCallMissed] = useState(false);
  const [showQuickQuestions, setShowQuickQuestions] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { toast } = useToast();
  const authedUser: AppUser | null = getUser();

  const quickQuestions = [
    "Какие документы нужны для поступления?",
    "Как подготовиться к собеседованию?",
    "Когда лучше подавать документы?",
    "Как выбрать университет?",
  ];

  const userTypeLabel = {
    school: "школьник",
    graduate: "выпускник", 
    student: "студент"
  };

  // Initial greeting
  useEffect(() => {
    if (messages.length === 0) {
      const greeting: Message = {
        id: "welcome",
        sender: "consultant",
        text: `Здравствуйте, ${userName}! Я ваш персональный консультант по поступлению. Рад помочь вам с выбором университета и подготовкой документов.`,
        timestamp: new Date(),
        suggestions: quickQuestions,
      };
      setMessages([greeting]);
    }
  }, [userName, messages.length]);

  // Scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = () => {
    if (!input.trim()) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      sender: "user",
      text: input,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInput("");
    setShowQuickQuestions(false);

    // Simulate consultant response
    setTimeout(() => {
      const consultantResponse: Message = {
        id: (Date.now() + 1).toString(),
        sender: "consultant",
        text: "Спасибо за ваш вопрос! Я изучу вашу ситуацию и soon отвечу подробно. А пока давайте обсудим ваши цели в поступлении.",
        timestamp: new Date(),
      };
      setMessages(prev => [...prev, consultantResponse]);
    }, 1000);
  };

  const handleVideoCall = () => {
    setVideoCallActive(true);
    toast({
      title: "Видеозвонок",
      description: "Консультант скоро присоединится к звонку",
    });
  };

  const handleScheduleMeeting = () => {
    if (onOpenCalendar) {
      onOpenCalendar();
    } else {
      toast({
        title: "Календарь",
        description: "Выберите удобное время для встречи",
      });
    }
  };

  return (
    <div className="fixed bottom-4 right-4 w-96 h-[600px] bg-background border border-border rounded-2xl shadow-2xl flex flex-col z-50">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-border">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
            <User className="w-5 h-5 text-primary" />
          </div>
          <div>
            <h3 className="font-semibold text-foreground">Консультант</h3>
            <p className="text-xs text-muted-foreground">Онлайн</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button size="sm" variant="ghost" onClick={handleVideoCall}>
            <Video className="w-4 h-4" />
          </Button>
          <Button size="sm" variant="ghost" onClick={onClose}>
            <X className="w-4 h-4" />
          </Button>
        </div>
      </div>

      {/* Profile Section */}
      {showProfile && (
        <div className="p-4 bg-secondary/5 border-b border-border">
          <div className="flex items-center justify-between mb-2">
            <h4 className="font-medium text-foreground">Профиль студента</h4>
            <Button 
              size="sm" 
              variant="ghost" 
              onClick={() => setShowProfile(false)}
            >
              <ChevronUp className="w-4 h-4" />
            </Button>
          </div>
          <div className="space-y-1 text-sm">
            <p><span className="font-medium">Имя:</span> {userName}</p>
            <p><span className="font-medium">Тип:</span> {userTypeLabel[userType]}</p>
            {dream && <p><span className="font-medium">Цель:</span> {dream}</p>}
            {universities.length > 0 && (
              <p><span className="font-medium">Университеты:</span> {universities.join(", ")}</p>
            )}
            {meetingTime && (
              <p><span className="font-medium">Встреча:</span> {meetingTime}</p>
            )}
          </div>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        <AnimatePresence>
          {messages.map((message) => (
            <motion.div
              key={message.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              className={`flex ${message.sender === "user" ? "justify-end" : "justify-start"}`}
            >
              <div
                className={`max-w-[80%] p-3 rounded-xl ${
                  message.sender === "user"
                    ? "bg-primary text-primary-foreground"
                    : "bg-secondary text-secondary-foreground"
                }`}
              >
                <p className="text-sm">{message.text}</p>
                {message.suggestions && (
                  <div className="mt-2 space-y-1">
                    {message.suggestions.map((suggestion, idx) => (
                      <Button
                        key={idx}
                        size="sm"
                        variant="ghost"
                        className="h-auto p-2 text-left justify-start"
                        onClick={() => setInput(suggestion)}
                      >
                        {suggestion}
                      </Button>
                    ))}
                  </div>
                )}
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
        <div ref={messagesEndRef} />
      </div>

      {/* Quick Questions */}
      {showQuickQuestions && (
        <div className="p-4 border-t border-border">
          <p className="text-sm font-medium mb-2">Быстрые вопросы:</p>
          <div className="grid grid-cols-2 gap-2">
            {quickQuestions.slice(0, 4).map((question, idx) => (
              <Button
                key={idx}
                size="sm"
                variant="outline"
                className="h-auto p-2 text-xs"
                onClick={() => setInput(question)}
              >
                {question}
              </Button>
            ))}
          </div>
        </div>
      )}

      {/* Input */}
      <div className="p-4 border-t border-border">
        <div className="flex gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && sendMessage()}
            placeholder="Напишите сообщение..."
            className="flex-1 px-3 py-2 bg-background border border-border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary"
          />
          <Button size="sm" onClick={sendMessage} disabled={!input.trim()}>
            <Send className="w-4 h-4" />
          </Button>
        </div>
        <div className="flex gap-2 mt-2">
          <Button size="sm" variant="outline" onClick={handleScheduleMeeting}>
            <Calendar className="w-4 h-4 mr-1" />
            Назначить встречу
          </Button>
        </div>
      </div>
    </div>
  );
};

export default ConsultantChat;
